from pathlib import Path
import sys,subprocess,datetime,math,json
P=Path(__file__).parent;mode=sys.argv[1];assert mode in ['reference-custody','relay'];script='reference_custody.py' if mode=='reference-custody' else 'courier_guard.py';receipt='reference-archive-unit-exit.json' if mode=='reference-custody' else 'relay-unit-exit.json';unit='h368-x2-'+mode;assert not (P/receipt).exists();assert subprocess.run(['systemctl','--user','is-active',unit],capture_output=True,text=True).stdout.strip() not in ('active','activating');now=datetime.datetime.now(datetime.timezone.utc);rem=math.floor((datetime.datetime(2026,11,5,16,30,tzinfo=datetime.timezone.utc)-now).total_seconds());assert rem>0
cmd=['systemd-run','--user','--unit='+unit,'-p','CPUQuota=100%','-p','MemoryMax=6G','-p','MemorySwapMax=0','-p','RuntimeMaxSec='+str(rem),'-p','KillMode=control-group','-p','TimeoutStopSec=15','-p','StandardOutput=append:'+str(P/(mode+'.log')),'-p','StandardError=append:'+str(P/(mode+'.err')),'-p','ExecStopPost=/usr/bin/nice -n 19 /usr/bin/taskset -c 62 /usr/bin/python3 '+str(P/'source/capture_exit.py'),'--setenv=H368_EXIT_RECEIPT='+str(P/receipt)]
for k in ['OPENBLAS_NUM_THREADS','OMP_NUM_THREADS','MKL_NUM_THREADS','NUMEXPR_NUM_THREADS']:cmd+=['--setenv='+k+'=1']
cmd+=['/usr/bin/nice','-n','19','/usr/bin/taskset','-c','62','/usr/bin/python3',str(P/script)];subprocess.run(cmd,check=True);(P/(mode+'-launch.json')).write_text(json.dumps(dict(command=cmd,utc=now.isoformat(),invocation_id=subprocess.check_output(['systemctl','--user','show',unit,'-p','InvocationID','--value'],text=True).strip()),indent=2)+'\n')
